"""Satış CSV'sindeki alanları çözümler."""
from datetime import date

def tutar(metin):
    """Türkçe biçimli tutarı sayıya çevirir: "1.234,56" -> 1234.56, "7.250" -> 7250.0, "7,5" -> 7.5."""
    metin = metin.strip()
    if "," in metin:
        tam, kurus = metin.split(",")
        # Eğer kuruş kısmı boşsa veya sadece virgül varsa (örn: "10,"), hata almamak için kontrol edilebilir 
        # ama mevcut veri yapısında "89,90" gibi görünüyor.
        # Asıl sorun: tam kısmındaki noktalar binlik ayracıdır ve kaldırılmalıdır.
        return float(tam.replace(".", "")) + float(kurus) / 100
    else:
        # Eğer nokta varsa ama virgül yoksa, bu bir ondalık mı yoksa binlik mi?
        # Veride "32.500" gibi değerler var. Bu muhtemelen 32500.0 olmalı.
        # Ancak "7.250,50" formatında nokta binlik ayracı.
        # Eğer metinde virgül yoksa ve nokta varsa, bu bir binlik ayırıcıdır (Türkçe formatı).
        if "." in metin:
            return float(metin.replace(".", ""))
        return float(metin)

def tarih(metin):
    """"GG.AA.YYYY" biçimindeki tarihi date nesnesine çevirir."""
    a, g, y = metin.strip().split(".")
    return date(int(y), int(a), int(g))

